// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(alice, 2 ether);
        vm.prank(alice);
        (bool ok,) = address(c).call{value: 1 ether}("");
        require(ok);
        address target = address(0x456);
        vm.deal(address(c), 1 ether);
        vm.prank(c.owner());
        c.sendMoney(target, 0.5 ether);
        assertTrue(c.depositsCount() == 1);
    }
}
